"""
restore_db.py - Run this ONCE in Render Shell to restore the database.
After running, delete this file.

Usage in Render Shell:
    python restore_db.py
"""
import base64, os, sys

DB_PATH = "/app/data_volume/pokeempire.db"

# The base64-encoded database will be embedded below by the setup script
B64_DATA = ""

def restore():
    if B64_DATA == "":
        print("ERROR: B64 data not embedded. Run embed_and_push.py first.")
        sys.exit(1)
    
    os.makedirs("/app/data_volume", exist_ok=True)
    
    if os.path.exists(DB_PATH):
        print(f"⚠️  Existing DB found at {DB_PATH}")
        confirm = input("Overwrite? (yes/no): ").strip().lower()
        if confirm != "yes":
            print("Aborted.")
            return
    
    data = base64.b64decode(B64_DATA)
    with open(DB_PATH, "wb") as f:
        f.write(data)
    
    size = os.path.getsize(DB_PATH)
    print(f"✅ Database restored successfully!")
    print(f"   Path: {DB_PATH}")
    print(f"   Size: {size/1024:.1f} KB")
    print(f"\n🔄 Restart your Render service to apply the database.")

if __name__ == "__main__":
    restore()
